CREATE OR REPLACE FUNCTION public.match_job_to_worker(_job_id uuid,_worker_id uuid) RETURNS TABLE(score integer,budget_score integer,sector_score integer,distance_score integer,urgency_score integer,distance_km numeric,breakdown jsonb) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE caller_id uuid:=auth.uid(); j record; w record; s_budget integer:=0; s_sector integer:=0; s_distance integer:=0; s_urgency integer:=0; est_km numeric:=NULL; shared_prefix integer:=0; BEGIN IF caller_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; SELECT id,owner_id,trade,estimated_budget,location_zip,city,urgency INTO j FROM public.jobs WHERE id=_job_id; IF j IS NULL THEN RAISE EXCEPTION 'Job not found'; END IF; IF caller_id<>j.owner_id AND caller_id<>_worker_id THEN RAISE EXCEPTION 'Not allowed to score this job/worker pair'; END IF; SELECT id,trades,min_project_size,service_radius_km,postal_code,city INTO w FROM public.profiles WHERE id=_worker_id; IF w IS NULL THEN RAISE EXCEPTION 'Worker profile not found'; END IF; IF j.estimated_budget IS NULL THEN s_budget:=18; ELSIF coalesce(w.min_project_size,0)=0 THEN s_budget:=30; ELSIF j.estimated_budget>=w.min_project_size*2 THEN s_budget:=35; ELSIF j.estimated_budget>=w.min_project_size THEN s_budget:=28; ELSE s_budget:=greatest(0,round(35.0*j.estimated_budget/nullif(w.min_project_size,0))::integer/2); END IF; IF j.trade IS NULL THEN s_sector:=10; ELSIF w.trades IS NOT NULL AND j.trade=ANY(w.trades) THEN s_sector:=30; ELSE s_sector:=0; END IF; IF j.location_zip IS NULL OR w.postal_code IS NULL THEN IF j.city IS NOT NULL AND w.city IS NOT NULL AND lower(trim(j.city))=lower(trim(w.city)) THEN s_distance:=20; est_km:=10; ELSE s_distance:=10; END IF; ELSE WHILE shared_prefix<least(length(j.location_zip),length(w.postal_code)) AND substr(j.location_zip,shared_prefix+1,1)=substr(w.postal_code,shared_prefix+1,1) LOOP shared_prefix:=shared_prefix+1; END LOOP; est_km:=CASE shared_prefix WHEN 0 THEN 400 WHEN 1 THEN 150 WHEN 2 THEN 50 WHEN 3 THEN 15 ELSE 3 END; IF est_km<=coalesce(w.service_radius_km,50) THEN s_distance:=CASE WHEN shared_prefix>=4 THEN 25 WHEN shared_prefix=3 THEN 22 WHEN shared_prefix=2 THEN 18 WHEN shared_prefix=1 THEN 12 ELSE 6 END; ELSE s_distance:=0; END IF; END IF; s_urgency:=CASE lower(coalesce(j.urgency,'normal')) WHEN 'emergency' THEN 10 WHEN 'urgent' THEN 9 WHEN 'normal' THEN 6 WHEN 'flexible' THEN 4 ELSE 5 END; RETURN QUERY SELECT least(100,s_budget+s_sector+s_distance+s_urgency),s_budget,s_sector,s_distance,s_urgency,est_km,jsonb_build_object('budget',jsonb_build_object('score',s_budget,'max',35,'job_budget',j.estimated_budget,'worker_min',w.min_project_size),'sector',jsonb_build_object('score',s_sector,'max',30,'job_trade',j.trade,'worker_trades',to_jsonb(w.trades)),'distance',jsonb_build_object('score',s_distance,'max',25,'estimated_km',est_km,'radius_km',w.service_radius_km),'urgency',jsonb_build_object('score',s_urgency,'max',10,'job_urgency',j.urgency)); END; $$;
REVOKE EXECUTE ON FUNCTION public.match_job_to_worker(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.match_job_to_worker(uuid,uuid) TO authenticated;